<style>
    .partner-page{padding:26px;background:#f5f7fb;min-height:calc(100vh - 80px)}
    .partner-wrap{max-width:1180px;margin:0 auto}.partner-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:20px}
    .partner-head h1{margin:0;color:#102a56;font-size:27px}.partner-head p{margin:6px 0;color:#64748b}.partner-actions{display:flex;gap:8px;flex-wrap:wrap}
    .panel{background:#fff;border:1px solid #e2e8f0;border-radius:15px;padding:18px;box-shadow:0 8px 24px rgba(15,23,42,.04)}
    .panel h2{margin:0 0 14px;font-size:17px;color:#102a56}.row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #eef2f7}.row:last-child{border-bottom:0}
    .muted{color:#64748b;font-size:12px}.badge{display:inline-block;border-radius:999px;padding:5px 9px;background:#f1f5f9;color:#475569;font-size:11px;font-weight:700}
    .btn{display:inline-block;border:0;border-radius:8px;padding:9px 12px;text-decoration:none;cursor:pointer;font-weight:700;font-size:12px;background:#2563eb;color:#fff}.btn.light{background:#eef2ff;color:#1d4ed8}
    table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eef2f7;text-align:left;font-size:13px}th{font-size:11px;color:#64748b;text-transform:uppercase}.table-wrap{overflow:auto}
    .form-control{width:100%;box-sizing:border-box;margin:4px 0 10px}.notice{background:#ecfdf5;color:#047857;padding:12px;border-radius:9px;margin-bottom:15px}
    @media(max-width:760px){.partner-head{flex-direction:column}.partner-page{padding:16px}}
</style>
